async (page) => {
 const report = {scope:"SYNTHETIC browser interception; not real TLS/listener/Windows acceptance",steps:[],screenshots:[],requests:[]};
 const check=(ok,name)=>{if(!ok)throw new Error(name);report.steps.push({name,status:"PASS"});};
 let phase="setup", authorized=false,allowGrant=false,pollDenied=false,force401=false,creates=0,polls=0,logouts=0,sessions=0;
 const proof="a".repeat(64),csrf="b".repeat(64),bearer="c".repeat(64),calls=[],errors=[],cspErrors=[];
 const onError=e=>errors.push(e.message);page.on("pageerror",onError);const onConsole=msg=>{if(msg.type()==="error"&&/Content Security Policy|Refused to|violates.*directive|unsafe-inline/i.test(msg.text()))cspErrors.push(msg.text());};page.on("console",onConsole);
 try {
 await page.unroute("https://board.synthetic/**");
 await page.context().clearCookies({name:"__Host-FutureClassroom",domain:"board.synthetic"});
 await page.setViewportSize({width:1440,height:1000});
 await page.goto("http://172.30.0.2:4173/fc/");
 await page.getByText("请使用管理员提供的可信 HTTPS 地址。HTTP 预览不会发送配对码或会话凭据。").waitFor();
 check(await page.locator("input").count()===0,"HTTP_preview_HTTPS_only_no_credentials");
 const csp="default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'self' blob: data:; media-src blob:; base-uri 'none'; object-src 'none'; frame-ancestors 'none'; form-action 'self'";
 await page.route("https://board.synthetic/**",async route=>{
  const request=route.request(),url=new URL(request.url());
  if(!url.pathname.startsWith("/fc/api/v1/")){
   const response=await route.fetch({url:"http://172.30.0.2:4173"+url.pathname});
   await route.fulfill({response,headers:{...response.headers(),"content-security-policy":csp,"x-content-type-options":"nosniff","referrer-policy":"no-referrer","permissions-policy":"camera=(), geolocation=(), microphone=(self)"}});return;
  }
  const path=url.pathname.slice(11),headers=request.headers(),body=request.postDataJSON();
  calls.push({path,method:request.method(),tick:Date.now(),queryEmpty:!url.search,originOK:request.method()!=="POST"||headers.origin==="https://board.synthetic",hasCsrf:!!headers["x-fc-csrf"]});
  const answer=(status,value,extra={})=>route.fulfill({status,headers:{"content-type":"application/json","cache-control":"no-store",...extra},body:JSON.stringify(value)});
  if(path==="status"){await answer(200,{schemaVersion:1,apiVersion:1,uiCompatibilityVersion:1,online:true});return;}
  if(path==="session"){
   sessions++;
   if(force401||!authorized||!headers.cookie?.includes("__Host-FutureClassroom="+bearer)){await answer(401,{schemaVersion:1,code:"UNAUTHORIZED"});return;}
   await answer(200,{schemaVersion:1,status:"AUTHENTICATED",principal:{id:"18446744073709551615",displayName:"合成测试教师",role:"TEACHER_ADMIN"},currentClassId:"42",assignments:[{classId:"42",subjectId:"7"}],csrf});return;
  }
  if(path==="pairing/requests"){
   creates++;if(body?.code!=="01234567"||Object.keys(body).sort().join(",")!=="code,deviceName,loginName,schemaVersion")throw new Error("invalid_create_shape");
   await answer(202,{schemaVersion:1,status:"PENDING",requestId:"18446744073709551615",pollSecret:proof,retryAfterMs:500});return;
  }
  if(path==="pairing/requests/18446744073709551615/poll"){
   polls++;if(body?.pollSecret!==proof||Object.keys(body).sort().join(",")!=="pollSecret,schemaVersion")throw new Error("invalid_poll_proof");
   if(pollDenied){await answer(403,{schemaVersion:1,code:"FORBIDDEN"});return;}
   if(!allowGrant){await answer(202,{schemaVersion:1,status:"PENDING",retryAfterMs:500});return;}
   authorized=true;await answer(200,{schemaVersion:1,status:"AUTHORIZED"},{"set-cookie":"__Host-FutureClassroom="+bearer+"; Path=/; Secure; HttpOnly; SameSite=Strict"});return;
  }
  if(path==="session/logout"){logouts++;if(headers["x-fc-csrf"]!==csrf||JSON.stringify(body)!=='{"schemaVersion":1}')throw new Error("invalid_private_csrf");await answer(503,{schemaVersion:1,code:"RESULT_UNKNOWN"});return;}
  await answer(404,{schemaVersion:1,code:"NOT_FOUND"});
 });
 phase="compatible_form";await page.goto("https://board.synthetic/fc/");await page.locator("#pair-code").waitFor({timeout:10000});
 check(await page.locator("form").count()===1,"HTTPS_synthetic_compatible_anonymous_form");
 check(!await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),"desktop1440_no_horizontal_overflow");
 await page.screenshot({path:"/tmp/fc-round11-pairing-desktop.png",fullPage:true});report.screenshots.push("/tmp/fc-round11-pairing-desktop.png");
 await page.setViewportSize({width:390,height:844});
 check(!await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),"mobile390_pairing_no_horizontal_overflow");
 await page.screenshot({path:"/tmp/fc-round11-pairing-mobile.png",fullPage:true});report.screenshots.push("/tmp/fc-round11-pairing-mobile.png");
 phase="keyboard_submit";await page.locator("#pair-code").focus();await page.keyboard.type("01234567");await page.keyboard.press("Tab");
 check(await page.locator("#login-name").evaluate(e=>document.activeElement===e),"keyboard_code_to_login");
 await page.keyboard.type("synthetic-teacher");await page.keyboard.press("Tab");
 check(await page.locator("#device-name").evaluate(e=>document.activeElement===e),"keyboard_login_to_device");
 await page.keyboard.type("Synthetic QA tablet");await page.keyboard.press("Tab");await page.keyboard.press("Enter");
 phase="pending";await page.getByRole("heading",{name:"等待白板管理员批准"}).waitFor({timeout:10000});await page.waitForTimeout(1150);
 check(creates===1&&polls>=2,"one_create_only_original_secret_POST_poll");
 const pp=calls.filter(c=>c.path.endsWith("/poll"));
 check(pp.every((c,i)=>i===0||c.tick-pp[i-1].tick>=490),"poll_min500ms_10ms_measurement_tolerance");
 check(!(await page.locator("body").innerText()).includes(proof),"poll_secret_not_rendered");
 phase="grant_session";allowGrant=true;await page.getByRole("heading",{name:/你好，合成测试教师/}).waitFor({timeout:10000});
 check(sessions>=2,"AUTHORIZED_followed_by_GETsession_actual_identity");
 check(await page.getByText("班级 ID 42",{exact:true}).first().isVisible(),"actual_current_class");
 check(await page.getByRole("button",{name:"尚未接入服务"}).count()===4,"four_partial_business_entries");
 check(await page.getByRole("button",{name:"尚未接入服务"}).evaluateAll(es=>es.every(e=>e.disabled)),"business_submissions_disabled");
 const cookies=(await page.context().cookies("https://board.synthetic")).filter(c=>c.name==="__Host-FutureClassroom");
 check(cookies.length===1&&cookies[0].secure&&cookies[0].httpOnly&&cookies[0].sameSite==="Strict","synthetic_Secure_HttpOnly_Strict_cookie");
 check(!(await page.evaluate(()=>document.cookie)).includes("__Host-FutureClassroom"),"bearer_not_JS_readable");
 check(!await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),"mobile390_session_no_horizontal_overflow");
 await page.setViewportSize({width:1440,height:1000});await page.screenshot({path:"/tmp/fc-round11-session-desktop.png",fullPage:true});report.screenshots.push("/tmp/fc-round11-session-desktop.png");
 phase="unknown_logout";await page.getByRole("button",{name:"注销账号",exact:true}).click();await page.getByRole("heading",{name:"注销结果尚未确认"}).waitFor({timeout:10000});await page.waitForTimeout(1100);
 check(logouts===1,"503_RESULT_UNKNOWN_no_POST_retry");check(!(await page.locator("body").innerText()).includes("合成测试教师"),"unknown_logout_clears_local_mirror");
 const old=sessions;await page.getByRole("button",{name:"核对白板会话"}).click();await page.getByRole("heading",{name:/你好，合成测试教师/}).waitFor({timeout:10000});
 check(sessions===old+1&&logouts===1,"manual_GET_only_recheck");
 phase="401";force401=true;await page.getByRole("button",{name:"核对会话",exact:true}).click();await page.locator("#pair-code").waitFor({timeout:10000});
 check(!(await page.locator("body").innerText()).includes("合成测试教师"),"401_session_UI_cleared");
 phase="403";pollDenied=true;allowGrant=false;await page.locator("#pair-code").fill("01234567");await page.locator("#login-name").fill("synthetic-teacher");await page.locator("#device-name").fill("Synthetic retry");await page.getByRole("button",{name:"申请连接"}).click();
 await page.getByText("申请已失效或授权被拒绝。请让白板管理员重新开启配对窗口后再申请。").waitFor({timeout:10000});
 const stopped=polls;await page.waitForTimeout(1100);check(polls===stopped&&creates===2,"403_stops_polling_no_create_retry");
 check(await page.evaluate(()=>localStorage.length===0&&sessionStorage.length===0),"no_browser_storage");
 check(calls.every(c=>c.queryEmpty&&c.originOK),"no_secret_URL_automatic_POST_Origin");
 check(calls.filter(c=>c.path==="session/logout").every(c=>c.hasCsrf)&&calls.filter(c=>c.path.startsWith("pairing/")).every(c=>!c.hasCsrf),"CSRF_private_POST_only");
 check(errors.length===0,"no_uncaught_runtime_errors");check(cspErrors.length===0,"production_CSP_nosniff_no_security_console_errors");report.cspErrors=cspErrors;report.status="PASS";
 }catch(error){report.status="FAIL";report.failurePhase=phase;report.error=String(error);report.currentText=await page.locator("body").innerText();}
 report.requests=calls;report.counts={creates,polls,logouts,sessions};report.browser=await page.evaluate(()=>navigator.userAgent);page.off("pageerror",onError);page.off("console",onConsole);return report;
}
